    .select({ orgId: organizationRetiredSlugs.orgId })
    .from(organizationRetiredSlugs)
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        gt(organizationRetiredSlugs.retiredAt, holdCutoff(new Date())),
