/**
 * Renaming a workspace slug (ADR 0005): retired slugs keep resolving for
 * `ORG_SLUG_HOLD_DAYS`, nobody else can take them, and a no-op publishes nothing.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { TenantScopeError } from "@/lib/tenant";
import { renameOrganizationSlugSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import { listActivity } from "@/server/services/activity-service";
import {
  createOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const START = new Date("2026-04-01T09:00:00.000Z");

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];

function capture(): TaskflowEventMap["organization.slug_changed"][] {
  const seen: TaskflowEventMap["organization.slug_changed"][] = [];
  detachers.push(subscribe("organization.slug_changed", (payload) => void seen.push(payload)));
  return seen;
}

function rename(slug: string, who: Tenant = tenant) {
  return renameOrganizationSlug(who.actors.admin, { orgId: who.org.id, slug });
}

function at(offsetMs: number): void {
  vi.setSystemTime(new Date(START.getTime() + offsetMs));
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("rename-me");
  other = await createTenant("bystander");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlug", () => {
  it("validates input with the shared slug rules", () => {
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId: tenant.org.id, slug: "Bad Slug" }).success,
    ).toBe(false);
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId: tenant.org.id, slug: "settings" }).success,
    ).toBe(false);
  });

  it("makes the new slug current everywhere and keeps the old one resolving", async () => {
    vi.useFakeTimers();
    at(0);
    const seen = capture();

    const renamed = await rename("rebrand");

    expect(renamed.slug).toBe("rebrand");
    expect(renamed.name).toBe(tenant.org.name);
    expect(renamed.plan).toBe(tenant.org.plan);
    expect(renamed.settings).toEqual(tenant.org.settings);

    const summary = await getOrganizationSummary(tenant.actors.member, tenant.org.id);
    expect(summary.organization.slug).toBe("rebrand");
    const listed = await listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.map((org) => org.slug)).toEqual(["rebrand"]);

    expect((await resolveOrgBySlug("rebrand"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("rename-me"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("rename-me"))?.slug).toBe("rebrand");

    const principal = { userId: tenant.userIds.member } as SessionPrincipal;
    const viaOld = await resolveActorForOrg(principal, "rename-me");
    const viaNew = await resolveActorForOrg(principal, "rebrand");
    expect(viaOld).toEqual(tenant.actors.member);
    expect(viaNew).toEqual(tenant.actors.member);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "rename-me",
      to: "rebrand",
    });

    const audit = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "rename-me", to: "rebrand" },
    });
  });

  it("releases the old slug at exactly ORG_SLUG_HOLD_DAYS", async () => {
    vi.useFakeTimers();
    const hold = ORG_SLUG_HOLD_DAYS * MS_PER_DAY;

    at(hold - 1);
    expect((await resolveOrgBySlug("rename-me"))?.id).toBe(tenant.org.id);

    at(hold);
    expect(await resolveOrgBySlug("rename-me")).toBeNull();
    expect(await orgRepo.findOrgBySlug("rename-me")).toBeNull();
    expect(await resolveActorForOrg({ userId: tenant.userIds.member } as SessionPrincipal, "rename-me")).toBeNull();
  });

  it("refuses a slug another workspace holds, current or retired, without suffixing", async () => {
    vi.useFakeTimers();
    at(1_000);

    await expect(rename(other.org.slug)).rejects.toBeInstanceOf(InvalidSlugError);
    // rebrand is current; rename-me was released in the previous test, so move
    // the bystander onto a slug it then retires inside the window.
    await rename("rebrand-2");
    await expect(rename("settings")).rejects.toBeInstanceOf(InvalidSlugError);

    const refused = await renameOrganizationSlug(other.actors.admin, {
      orgId: other.org.id,
      slug: "bystander-new",
    });
    expect(refused.slug).toBe("bystander-new");

    // "rebrand" is now retired by `tenant` (released only after the hold).
    await expect(rename("bystander")).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(
      renameOrganizationSlug(other.actors.admin, { orgId: other.org.id, slug: "rebrand" }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(other.org.id))?.slug).toBe("bystander-new");
  });

  it("keeps every earlier slug on its own hold and lets the owner rename back", async () => {
    vi.useFakeTimers();
    const day = MS_PER_DAY;
    at(2 * day);

    const seen = capture();
    await rename("rebrand-3");

    // rebrand (retired at ~0), rebrand-2 (retired at 1s), rename-me (lapsed).
    expect((await resolveOrgBySlug("rebrand-2"))?.slug).toBe("rebrand-3");
    expect((await resolveOrgBySlug("rebrand"))?.slug).toBe("rebrand-3");

    // Renaming back ends that slug's retirement and retires the one replaced.
    await rename("rebrand");
    expect((await resolveOrgBySlug("rebrand"))?.slug).toBe("rebrand");
    expect((await resolveOrgBySlug("rebrand-3"))?.slug).toBe("rebrand");
    expect(seen.map((event) => [event.from, event.to])).toEqual([
      ["rebrand-2", "rebrand-3"],
      ["rebrand-3", "rebrand"],
    ]);

    // The first retirement lapses on its own schedule, unaffected by the later ones.
    at(ORG_SLUG_HOLD_DAYS * day + 1_000);
    expect(await resolveOrgBySlug("rebrand-2")).toBeNull();
    expect((await resolveOrgBySlug("rebrand-3"))?.slug).toBe("rebrand");

    // A lapsed slug is free for anybody, including by rename.
